  for(const q of m.questions){assert(q.evidenceParagraphIds.length);assert(q.evidenceParagraphIds.every(id=>m.paragraphs.some(p=>p.id===id)));assert(q.rationale);assert.equal(q.answerKeyStatus,'standard')}
  for(let count=0;count<=5;count++){
   const survey={submittedAt:'2026-10-30',questionnaireVersion:m.questionnaireVersion,culturalScore:999,effort:1,flow:1,agency:1,informationLoad:1,engagement:1};m.questions.forEach((q,i)=>survey[q.id]=i<count?keys[i]:(keys[i]+1)%4);const task={material,survey},before=JSON.stringify(task),g=x.scoreComprehension(task);
   assert.equal(g.status,'scored');assert.equal(g.score,count);assert.equal(g.maxScore,5);assert.equal(g.items.filter(i=>i.correct).length,count);assert.equal(JSON.stringify(task),before);
   survey.effort=9;survey.flow=7;assert.equal(x.scoreComprehension(task).score,count); // Subjective ratings cannot affect correctness.
  }
  const base={material,survey:{submittedAt:'2026-10-30',questionnaireVersion:'culture-inference-5-draft-v2',...Object.fromEntries(m.questions.map((q,i)=>[q.id,keys[i]]))}};
  assert.equal(x.scoreComprehension(base).score,5);delete base.survey[m.questions[0].id];assert.equal(x.scoreComprehension(base).status,'incomplete_answers');assert.equal(x.scoreComprehension(base).score,null);
  base.survey[m.questions[0].id]='0';assert.equal(x.scoreComprehension(base).score,null);base.survey[m.questions[0].id]=5;assert.equal(x.scoreComprehension(base).score,null);base.survey[m.questions[0].id]=keys[0];base.survey.questionnaireVersion='different-questions';assert.equal(x.scoreComprehension(base).status,'incompatible_questionnaire');delete base.survey.questionnaireVersion;assert.equal(x.scoreComprehension(base).score,5);delete base.survey.submittedAt;assert.equal(x.scoreComprehension(base).status,'not_submitted');
